// spec: Реклама — где показывается и где нет
// seed: tests/seed.user.spec.ts
import path from 'node:path';
import { endMonitoring } from '../helpers/monitor';
import { test, expect } from '@playwright/test';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });

test.describe('Реклама — где показывается и где нет', () => {
  test('Нет рекламы во время мониторинга и в окне тревоги #840d8543 #a5b844f5 @iphone @data', async ({ page }) => {
    // 1. Navigate to /home?mock=headUnder
    await page.goto('https://banci.expo.app/home?mock=headUnder');

    // 2. Start monitoring and pass the setup steps
    await page.getByRole('button', { name: 'התחלת ניטור' }).click();
    await page.getByRole('button', { name: 'עוצמת צפצוף מקסימלית' }).click();
    await page.getByRole('button', { name: 'השמעה' }).click();
    await page.getByRole('button', { name: 'שמעתי' }).click();
    await page.getByRole('button', { name: 'המשך' }).click();
    await page.getByRole('button', { name: 'המשך' }).click();
    const selectAll = page.getByRole('button', { name: 'בחירת כולם' });
    if (await selectAll.isVisible()) {
      await selectAll.click();
    }
    await page.getByRole('button', { name: 'התחלת ניטור' }).click();

    // 3. On /monitor/live there is no ad
    await expect(page).toHaveURL(/\/monitor\/live/);
    await expect(page.getByText('פרסומת')).toHaveCount(0);

    // 4. Wait for the alarm sheet; no ad there either
    await expect(page.getByText('זוהתה סכנה בבריכה')).toBeVisible({ timeout: 45_000 });
    const slider = page.getByRole('button', { name: 'זו אזעקת שווא' });
    await expect(slider).toBeVisible();
    await expect(page.getByText('פרסומת')).toHaveCount(0);

    // 5. Cleanup: закрыть тревогу и завершить мониторинг (общий помощник)
    await endMonitoring(page);
  });
});
